type WorkspaceModule = "orders" | "suppliers" | "quotes" | "production" | "shirt_production" | "stock" | "transactions" | "assets" | "company" | "sublimation" | "marketing";

function usePersistentState<T>(key: WorkspaceModule, initial: T) {
  const { isAuthenticated, loading: authLoading } = useAuth();
  const initialRef = useRef(initial);
  const [value, setValue] = useState<T>(() => {
    try {
      const saved = typeof window !== "undefined" ? localStorage.getItem(`nocorre:${key}`) : null;
      return saved ? (JSON.parse(saved) as T) : initial;
    } catch {
      return initial;
    }
  });
  const [hydrated, setHydrated] = useState(false);
  const lastSaved = useRef<string | null>(null);
  const snapshotQuery = trpc.workspace.get.useQuery({ module: key }, { enabled: isAuthenticated && !authLoading, staleTime: Infinity });
  const saveSnapshot = trpc.workspace.save.useMutation({ onError: (error) => { lastSaved.current = null; toast.error(error.message || "Não foi possível salvar as alterações."); } });

  useEffect(() => {
    if (!snapshotQuery.isSuccess || hydrated) return;
    try {
      const saved = snapshotQuery.data.data ? (JSON.parse(snapshotQuery.data.data) as T) : initialRef.current;
      setValue(saved);
      lastSaved.current = JSON.stringify(saved);
    } catch {
      setValue(initialRef.current);
    }
    setHydrated(true);
  }, [hydrated, snapshotQuery.data?.data, snapshotQuery.isSuccess]);

  useEffect(() => {
    const serialized = JSON.stringify(value);
    if (typeof window !== "undefined") localStorage.setItem(`nocorre:${key}`, serialized);
    if (isAuthenticated && hydrated && serialized !== lastSaved.current) {
      lastSaved.current = serialized;
      saveSnapshot.mutate({ module: key, data: serialized });
    }
  }, [hydrated, isAuthenticated, key, saveSnapshot, value]);

  return [value, setValue] as const;
}

const money = (value: number) => value.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
const today = () => new Date().toLocaleDateString("pt-BR");
